                templateErrorEl.classList.add('visible');
            }

            function clearTemplateError() {
                templateErrorEl.textContent = '';
                templateErrorEl.classList.remove('visible');
            }

            function renderVariablesList() {
                variablesListEl.innerHTML = '';
                VARIABLES.forEach(v => {
                    const span = document.createElement('span');
                    span.className = 'variable-hint';
                    span.textContent = v.key;
                    span.title = v.description;
                    span.addEventListener('click', () => {
                        insertVariableAtCursor(v.key);
                    });
                    variablesListEl.appendChild(span);
                });
            }

            function insertVariableAtCursor(variableKey) {
                const textarea = templateHtmlEl;
                const start = textarea.selectionStart;
                const end = textarea.selectionEnd;
                const text = textarea.value;
                const newText = text.substring(0, start) + variableKey + text.substring(end);
                textarea.value = newText;
                // Place cursor after inserted variable
                const newCursorPos = start + variableKey.length;
                textarea.setSelectionRange(newCursorPos, newCursorPos);
                textarea.focus();
                // Trigger input event for any listeners
                textarea.dispatchEvent(new Event('input'));
            }

            function loadTemplate(templateName) {
                const template = TEMPLATES[templateName];
                if (template) {
                    templateHtmlEl.value = template.html;
                    currentTemplateName = templateName;
                    clearTemplateError();
                    // Update active chip
                    document.querySelectorAll('.template-chip').forEach(chip => {
                        chip.classList.toggle('active', chip.dataset.template === templateName);
                    });
                }
            }

            function generatePreview() {
                const templateHtml = templateHtmlEl.value;
                if (!templateHtml.trim()) {
                    showTemplateError('Template cannot be empty.');
                    showToast('Template is empty', 'error');
                    return;
                }

                // Check for unmatched variables
                const profileData = getProfileData();
                const knownKeys = Object.keys(profileData);
                const placeholderRegex = /\{\{(\w+)\}\}/g;
                let match;
                const foundPlaceholders = new Set();
                while ((match = placeholderRegex.exec(templateHtml)) !== null) {
                    foundPlaceholders.add(match[1]);
                }
                const unknownPlaceholders = [];
                foundPlaceholders.forEach(key => {
                    if (!knownKeys.includes(key)) {
                        unknownPlaceholders.push('{{' + key + '}}');
                    }
                });

                if (unknownPlaceholders.length > 0) {
                    showTemplateError('Unknown variables: ' + unknownPlaceholders.join(', '));
                    showToast('Unknown variables in template', 'error');
                    return;
                }

                clearTemplateError();

                const interpolatedHtml = interpolate(templateHtml, profileData);
                lastGeneratedHtml = interpolatedHtml;

                // Render preview
                previewAreaEl.innerHTML = interpolatedHtml;
                showToast('Preview generated successfully!');
            }

            function resetToTemplate() {
                loadTemplate(currentTemplateName);
                clearTemplateError();
                // Reset profile to defaults
                profileInputs.firstName.value = 'John';
                profileInputs.lastName.value = 'Doe';
                profileInputs.email.value = 'john.doe@example.com';
                profileInputs.company.value = 'Acme Inc.';
                profileInputs.role.value = 'Software Engineer';
                profileInputs.plan.value = 'Pro';
                profileInputs.accountCreated.value = '2024-01-15';
                profileInputs.lastLogin.value = '2024-06-20T09:30';
                profileInputs.unreadCount.value = '3';
                profileInputs.dashboardUrl.value = 'https://app.example.com/dashboard';
                previewAreaEl.innerHTML = '<p style="color: var(--text-secondary); font-style: italic;">Generate a preview to see the interpolated email.</p>';
                lastGeneratedHtml = '';
                showToast('Reset to defaults');
            }

            function copyHtml() {
                if (!lastGeneratedHtml) {
                    // Try to generate first
                    generatePreview();
                    if (!lastGeneratedHtml) return;
                }
                navigator.clipboard.writeText(lastGeneratedHtml).then(() => {
                    showToast('HTML copied to clipboard!');
                }).catch(() => {
                    // Fallback
                    const textarea = document.createElement('textarea');
                    textarea.value = lastGeneratedHtml;
                    document.body.appendChild(textarea);
                    textarea.select();
                    document.execCommand('copy');
                    document.body.removeChild(textarea);
                    showToast('HTML copied to clipboard!');
                });
            }

            // ============================================================
            // Event Listeners
            // ============================================================
            templateSelectorEl.addEventListener('click', (e) => {
                const chip = e.target.closest('.template-chip');
                if (chip) {
                    loadTemplate(chip.dataset.template);
                }
            });

            generateBtn.addEventListener('click', generatePreview);

            resetBtn.addEventListener('click', resetToTemplate);

            copyBtn.addEventListener('click', copyHtml);

            // Live preview on profile input change (debounced)
            let debounceTimer;
            function handleProfileChange() {
                clearTimeout(debounceTimer);
                debounceTimer = setTimeout(() => {
                    if (templateHtmlEl.value.trim()) {
                        generatePreview();
                    }
                }, 400);
            }

            Object.values(profileInputs).forEach(el => {
                el.addEventListener('input', handleProfileChange);
                el.addEventListener('change', handleProfileChange);
            });

            // Also regenerate when template is edited (debounced)
            templateHtmlEl.addEventListener('input', () => {
                clearTimeout(debounceTimer);
                debounceTimer = setTimeout(() => {
                    if (templateHtmlEl.value.trim()) {
                        generatePreview();
                    }
                }, 500);
            });

            // Keyboard shortcut: Ctrl+Enter to generate
            templateHtmlEl.addEventListener('keydown', (e) => {
                if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
                    e.preventDefault();
                    generatePreview();
                }
            });

            // ============================================================
            // Initialization
            // ============================================================
            function init() {
                renderVariablesList();
                loadTemplate('welcome');
                // Generate initial preview
                generatePreview();
            }

            init();
        })();
    </script>
</body>
</html>
